BufferedReader in = new BufferedReader(
    new InputStreamReader(s.getInputStream(), StandardCharsets.UTF_8));
PrintWriter out = new PrintWriter(
    new OutputStreamWriter(s.getOutputStream(), StandardCharsets.UTF_8), false);

String line;
while ((line = in.readLine()) != null) {      // 4.3절 그대로
    if (line.equals("bye")) { out.println("bye"); out.flush(); break; }
    out.println("echo: " + line);
    out.flush();                              // 이 줄이 이 절의 주제다
}

// FileInputStream 이 s.getInputStream() 으로 바뀐 것뿐이다.
// charset 을 적는 것도 4.2절과 같다 — 안 적으면 상대와 다를 수 있다.
